"""Rate limiting layer for the URL shortener API.

Design goals (see docs/ARCHITECTURE.md for the wider picture):

* A small storage interface (:class:`RateLimiterStore`) decouples the counting
  algorithm from where counts live, so the default in-memory dict-backed store
  can later be swapped for a shared store (e.g. Redis) without touching call
  sites in ``api.py``.
* :class:`RateLimiter` classifies a client (by IP, optionally honouring
  ``X-Forwarded-For`` when the peer is a configured trusted proxy), looks up a
  named rule (limit + window), and applies a thread-safe sliding-window
  counter keyed by ``(rule_name, client_id)``.
* Rules can be hot-reloaded at runtime via :meth:`RateLimiter.set_rule` (used
  by the ``PUT /admin/config/rate-limits/{ruleName}`` endpoint) without a
  process restart.
* Every allow/deny decision is counted in :class:`RateLimitMetrics` and logged,
  so abuse can be monitored via ``GET /admin/metrics``.
"""

from __future__ import annotations

import logging
import threading
import time
from collections import deque
from dataclasses import dataclass
from typing import Optional, Protocol

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class RateLimitRule:
    """A named limit: at most ``limit`` requests per ``window_seconds``."""

    limit: int
    window_seconds: float


@dataclass
class RateLimitResult:
    """Outcome of a single rate-limit check, ready to become HTTP headers."""

    allowed: bool
    limit: Optional[int]
    remaining: Optional[int]
    reset_at: Optional[float]

    def headers(self) -> list:
        """Standard ``X-RateLimit-*`` headers; empty if no rule applied."""

        if self.limit is None:
            return []
        now = time.time()
        reset_in = max(0, int(round((self.reset_at or now) - now)))
        return [
            ("X-RateLimit-Limit", str(self.limit)),
            ("X-RateLimit-Remaining", str(max(0, self.remaining or 0))),
            ("X-RateLimit-Reset", str(reset_in)),
        ]


class RateLimiterStore(Protocol):
    """Storage contract for sliding-window counters.

    Implementations must be safe to call concurrently from multiple threads
    (the standard-library WSGI server serves each request on its own thread
    when used with a threading mixin, and tests exercise this directly).
    """

    def hit(
        self, key: str, limit: int, window_seconds: float, now: Optional[float] = None
    ):
        """Record a hit for ``key`` and report whether it is within budget.

        Returns ``(allowed, remaining, reset_at)``.
        """
        ...


class InMemoryRateLimiterStore:
    """Sliding-window counter backed by a dict of deques, guarded by a lock.

    Kept intentionally simple (a timestamp log per key) since the service is
    single-instance; the :class:`RateLimiterStore` protocol is what makes it
    possible to later swap this for a shared backend (Redis, etc.) without any
    change to :class:`RateLimiter` or the API layer.
    """

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._buckets: dict = {}

    def hit(self, key: str, limit: int, window_seconds: float, now: Optional[float] = None):
        now = time.time() if now is None else now
        cutoff = now - window_seconds
        with self._lock:
            dq = self._buckets.setdefault(key, deque())
            while dq and dq[0] <= cutoff:
                dq.popleft()
            allowed = len(dq) < limit
            if allowed:
                dq.append(now)
            remaining = max(0, limit - len(dq))
            reset_at = (dq[0] + window_seconds) if dq else (now + window_seconds)
            return allowed, remaining, reset_at


class RateLimitMetrics:
    """In-memory counters of allow/deny decisions per rule, for monitoring."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._counts: dict = {}

    def record(self, rule_name: str, allowed: bool) -> None:
        with self._lock:
            key = (rule_name, allowed)
            self._counts[key] = self._counts.get(key, 0) + 1

    def snapshot(self) -> dict:
        with self._lock:
            result: dict = {}
            for (rule_name, allowed), count in self._counts.items():
                bucket = result.setdefault(rule_name, {"allowed": 0, "denied": 0})
                bucket["allowed" if allowed else "denied"] += count
            return result


class RateLimiter:
    """Classifies clients, applies named rules, and records outcomes."""

    def __init__(
        self,
        rules: dict,
        store: Optional[RateLimiterStore] = None,
        trusted_proxies: Optional[set] = None,
    ) -> None:
        self.store: RateLimiterStore = store or InMemoryRateLimiterStore()
        self._rules_lock = threading.Lock()
        self._rules: dict = dict(rules)
        self.trusted_proxies = set(trusted_proxies or set())
        self.metrics = RateLimitMetrics()

    # -- rule management (hot-reloadable, no redeploy needed) ---------------
    def set_rule(self, name: str, limit: int, window_seconds: float) -> None:
        with self._rules_lock:
            self._rules[name] = RateLimitRule(int(limit), float(window_seconds))

    def get_rule(self, name: str) -> Optional[RateLimitRule]:
        with self._rules_lock:
            return self._rules.get(name)

    def rules_snapshot(self) -> dict:
        with self._rules_lock:
            return {
                name: {"limit": rule.limit, "window_seconds": rule.window_seconds}
                for name, rule in self._rules.items()
            }

    # -- client identification ----------------------------------------------
    def client_id(self, environ: dict) -> str:
        remote = environ.get("REMOTE_ADDR") or "unknown"
        trusted = self.trusted_proxies
        if trusted and ("*" in trusted or remote in trusted):
            forwarded = environ.get("HTTP_X_FORWARDED_FOR")
            if forwarded:
                return forwarded.split(",")[0].strip()
        return remote

    # -- the actual check -----------------------------------------------------
    def check(self, rule_name: str, environ: dict, now: Optional[float] = None) -> RateLimitResult:
        rule = self.get_rule(rule_name)
        if rule is None:
            # No rule configured for this name: allow, no headers emitted.
            return RateLimitResult(True, None, None, None)
        client = self.client_id(environ)
        key = f"{rule_name}:{client}"
        allowed, remaining, reset_at = self.store.hit(key, rule.limit, rule.window_seconds, now=now)
        self.metrics.record(rule_name, allowed)
        if not allowed:
            logger.warning("rate limit exceeded: rule=%s client=%s", rule_name, client)
        return RateLimitResult(allowed, rule.limit, remaining, reset_at)


def build_default_limiter() -> RateLimiter:
    """Build a :class:`RateLimiter` from environment-driven config defaults."""

    from . import config

    rules = {
        "shorten": RateLimitRule(config.RATE_LIMIT_SHORTEN_LIMIT, config.RATE_LIMIT_SHORTEN_WINDOW),
        "redirect": RateLimitRule(config.RATE_LIMIT_REDIRECT_LIMIT, config.RATE_LIMIT_REDIRECT_WINDOW),
        "admin": RateLimitRule(config.RATE_LIMIT_ADMIN_LIMIT, config.RATE_LIMIT_ADMIN_WINDOW),
    }
    return RateLimiter(rules=rules, trusted_proxies=config.TRUSTED_PROXIES)

"""WSGI HTTP adapter over :class:`ShortenerService`.

Kept as a plain WSGI callable so it runs on the standard-library server and is
trivially testable without booting a socket (see ``tests/test_api.py``).
"""

from __future__ import annotations

import json
import logging
import time

from .analytics import AnalyticsService
from .ratelimit import RateLimiter, build_default_limiter
from .service import AliasError, InvalidURLError, ShortenerService

logger = logging.getLogger(__name__)

_REASON = {
    200: "OK",
    201: "Created",
    302: "Found",
    400: "Bad Request",
    404: "Not Found",
    429: "Too Many Requests",
    500: "Internal Server Error",
}


class WSGIApp:
    """Minimal router mapping HTTP requests onto the service.

    ``limiter`` is a :class:`~url_shortener.ratelimit.RateLimiter`-like object
    exposing ``check(rule_name, environ) -> RateLimitResult``. It guards link
    creation, redirects and admin/analytics routes with per-rule sliding
    window budgets, returning HTTP 429 with ``Retry-After`` when a client goes
    over budget and attaching ``X-RateLimit-*`` headers otherwise. Defaults to
    a config-driven in-memory limiter (see ``ratelimit.py``) when omitted.
    """

    def __init__(self, service: ShortenerService | None = None, limiter: RateLimiter | None = None) -> None:
        self.service = service or ShortenerService()
        self.analytics = AnalyticsService(self.service.store)
        self.limiter = limiter or build_default_limiter()

    def __call__(self, environ, start_response):
        method = environ.get("REQUEST_METHOD", "GET")
        path = environ.get("PATH_INFO", "/")
        try:
            if path in ("/healthz", "/health"):
                return self._json(start_response, 200, {"status": "ok"})

            if path == "/admin/metrics" and method == "GET":
                return self._with_rate_limit(
                    environ, start_response, "admin", lambda sr, extra: self._metrics(sr, extra)
                )

            if path.startswith("/admin/config/rate-limits/") and method == "PUT":
                rule_name = path[len("/admin/config/rate-limits/") :]
                return self._with_rate_limit(
                    environ,
                    start_response,
                    "admin",
                    lambda sr, extra: self._update_rule(environ, sr, rule_name, extra),
                )

            if path == "/api/shorten" and method == "POST":
                return self._with_rate_limit(
                    environ,
                    start_response,
                    "shorten",
                    lambda sr, extra: self._shorten(environ, sr, extra),
                )

            if path.startswith("/api/stats/") and method == "GET":
                code = path[len("/api/stats/") :]
                return self._with_rate_limit(
                    environ,
                    start_response,
                    "redirect",
                    lambda sr, extra: self._stats(sr, code, extra),
                )

            if method == "GET" and path != "/" and "/" not in path[1:]:
                code = path[1:]
                return self._with_rate_limit(
                    environ,
                    start_response,
                    "redirect",
                    lambda sr, extra: self._redirect(environ, sr, code, extra),
                )

            return self._json(start_response, 404, {"error": "not found"})
        except (InvalidURLError, AliasError) as exc:
            return self._json(start_response, 400, {"error": str(exc)})
        except Exception:  # defensive: never leak internals to the client
            return self._json(start_response, 500, {"error": "internal error"})

    # -- rate limiting glue ---------------------------------------------------
    def _with_rate_limit(self, environ, start_response, rule_name, handler):
        result = self.limiter.check(rule_name, environ)
        headers = result.headers()
        if not result.allowed:
            now = time.time()
            retry_after = max(0, int(round((result.reset_at or now) - now)))
            response_headers = list(headers) + [("Retry-After", str(retry_after))]
            return self._json(
                start_response,
                429,
                {"error": "rate limit exceeded", "retry_after": retry_after},
                extra_headers=response_headers,
            )
        return handler(start_response, headers)

    def _metrics(self, start_response, extra_headers=None):
        payload = {
            "rate_limits": self.limiter.rules_snapshot(),
            "metrics": self.limiter.metrics.snapshot(),
        }
        return self._json(start_response, 200, payload, extra_headers=extra_headers)

    def _update_rule(self, environ, start_response, rule_name, extra_headers=None):
        try:
            data = json.loads(self._read_body(environ) or "{}")
        except json.JSONDecodeError:
            return self._json(
                start_response, 400, {"error": "invalid JSON body"}, extra_headers=extra_headers
            )
        limit = data.get("limit")
        window_seconds = data.get("window_seconds", data.get("window"))
        valid = (
            isinstance(limit, (int, float))
            and not isinstance(limit, bool)
            and limit > 0
            and isinstance(window_seconds, (int, float))
            and not isinstance(window_seconds, bool)
            and window_seconds > 0
        )
        if not valid:
            return self._json(
                start_response,
                400,
                {"error": "limit and window_seconds must be positive numbers"},
                extra_headers=extra_headers,
            )
        self.limiter.set_rule(rule_name, int(limit), float(window_seconds))
        rule = self.limiter.get_rule(rule_name)
        return self._json(
            start_response,
            200,
            {"rule": rule_name, "limit": rule.limit, "window_seconds": rule.window_seconds},
            extra_headers=extra_headers,
        )

    # -- request handlers -------------------------------------------------
    def _shorten(self, environ, start_response, extra_headers=None):
        try:
            data = json.loads(self._read_body(environ) or "{}")
        except json.JSONDecodeError:
            return self._json(
                start_response, 400, {"error": "invalid JSON body"}, extra_headers=extra_headers
            )
        record = self.service.shorten(
            data.get("url"),
            custom_alias=data.get("alias"),
            ttl_seconds=data.get("ttl_seconds"),
        )
        return self._json(
            start_response,
            201,
            {
                "code": record.code,
                "short_url": self.service.short_url(record.code),
                "long_url": record.long_url,
                "expires_at": record.expires_at,
            },
            extra_headers=extra_headers,
        )

    def _redirect(self, environ, start_response, code, extra_headers=None):
        long_url = self.service.resolve(
            code,
            referrer=environ.get("HTTP_REFERER"),
            user_agent=environ.get("HTTP_USER_AGENT"),
        )
        if long_url is None:
            return self._json(
                start_response, 404, {"error": "unknown or expired code"}, extra_headers=extra_headers
            )
        headers = [("Location", long_url), ("Content-Length", "0")]
        if extra_headers:
            headers.extend(extra_headers)
        start_response("302 Found", headers)
        return [b""]

    def _stats(self, start_response, code, extra_headers=None):
        stats = self.service.stats(code)
        if stats is None:
            return self._json(
                start_response, 404, {"error": "unknown code"}, extra_headers=extra_headers
            )
        stats["analytics"] = self.analytics.report(code)
        return self._json(start_response, 200, stats, extra_headers=extra_headers)

    @staticmethod
    def _read_body(environ) -> str:
        try:
            length = int(environ.get("CONTENT_LENGTH") or 0)
        except (TypeError, ValueError):
            length = 0
        if length <= 0:
            return ""
        return environ["wsgi.input"].read(length).decode("utf-8")

    def _json(self, start_response, status, payload, extra_headers=None):
        body = json.dumps(payload).encode("utf-8")
        headers = [("Content-Type", "application/json"), ("Content-Length", str(len(body)))]
        if extra_headers:
            headers.extend(extra_headers)
        start_response(f"{status} {_REASON.get(status, 'OK')}", headers)
        return [body]


app = WSGIApp()

"""Tests for the rate limiting layer (unit + WSGI integration)."""

import io
import json
import unittest

from url_shortener.api import WSGIApp
from url_shortener.ratelimit import (
    InMemoryRateLimiterStore,
    RateLimiter,
    RateLimitRule,
)


def call(app, method, path, body=None, environ_extra=None):
    raw = (body or "").encode("utf-8")
    environ = {
        "REQUEST_METHOD": method,
        "PATH_INFO": path,
        "wsgi.input": io.BytesIO(raw),
        "CONTENT_LENGTH": str(len(raw)),
        "REMOTE_ADDR": "127.0.0.1",
    }
    if environ_extra:
        environ.update(environ_extra)
    captured = {}

    def start_response(status, headers):
        captured["status"] = status
        captured["headers"] = dict(headers)

    payload = b"".join(app(environ, start_response))
    return int(captured["status"].split()[0]), captured["headers"], payload


class InMemoryStoreTests(unittest.TestCase):
    def test_allows_up_to_limit_then_denies(self):
        store = InMemoryRateLimiterStore()
        t = 1000.0
        for _ in range(3):
            allowed, remaining, _ = store.hit("k", 3, 60, now=t)
            self.assertTrue(allowed)
        allowed, remaining, reset_at = store.hit("k", 3, 60, now=t)
        self.assertFalse(allowed)
        self.assertEqual(remaining, 0)

    def test_window_resets_over_time(self):
        store = InMemoryRateLimiterStore()
        t = 1000.0
        for _ in range(2):
            self.assertTrue(store.hit("k", 2, 10, now=t)[0])
        self.assertFalse(store.hit("k", 2, 10, now=t)[0])
        # Move past the window: budget should be available again.
        allowed, _, _ = store.hit("k", 2, 10, now=t + 11)
        self.assertTrue(allowed)


class RateLimiterTests(unittest.TestCase):
    def _limiter(self, **rules):
        return RateLimiter(rules=rules)

    def test_check_enforces_named_rule(self):
        limiter = self._limiter(test=RateLimitRule(2, 60))
        environ = {"REMOTE_ADDR": "1.2.3.4"}
        r1 = limiter.check("test", environ, now=100.0)
        r2 = limiter.check("test", environ, now=100.0)
        r3 = limiter.check("test", environ, now=100.0)
        self.assertTrue(r1.allowed)
        self.assertTrue(r2.allowed)
        self.assertFalse(r3.allowed)
        self.assertEqual(r3.limit, 2)

    def test_unconfigured_rule_allows_without_headers(self):
        limiter = self._limiter()
        result = limiter.check("missing", {"REMOTE_ADDR": "1.1.1.1"})
        self.assertTrue(result.allowed)
        self.assertEqual(result.headers(), [])

    def test_metrics_track_allow_and_deny(self):
        limiter = self._limiter(test=RateLimitRule(1, 60))
        environ = {"REMOTE_ADDR": "9.9.9.9"}
        limiter.check("test", environ, now=1.0)
        limiter.check("test", environ, now=1.0)
        snap = limiter.metrics.snapshot()
        self.assertEqual(snap["test"]["allowed"], 1)
        self.assertEqual(snap["test"]["denied"], 1)

    def test_client_id_ignores_forwarded_for_by_default(self):
        limiter = self._limiter(test=RateLimitRule(5, 60))
        environ = {"REMOTE_ADDR": "10.0.0.1", "HTTP_X_FORWARDED_FOR": "1.2.3.4"}
        self.assertEqual(limiter.client_id(environ), "10.0.0.1")

    def test_client_id_trusts_forwarded_for_when_configured(self):
        limiter = RateLimiter(
            rules={"test": RateLimitRule(5, 60)}, trusted_proxies={"10.0.0.1"}
        )
        environ = {"REMOTE_ADDR": "10.0.0.1", "HTTP_X_FORWARDED_FOR": "1.2.3.4, 10.0.0.1"}
        self.assertEqual(limiter.client_id(environ), "1.2.3.4")

    def test_set_rule_hot_reloads_limit(self):
        limiter = self._limiter(test=RateLimitRule(5, 60))
        limiter.set_rule("test", 1, 60)
        environ = {"REMOTE_ADDR": "5.5.5.5"}
        self.assertTrue(limiter.check("test", environ, now=0.0).allowed)
        self.assertFalse(limiter.check("test", environ, now=0.0).allowed)


class RateLimitIntegrationTests(unittest.TestCase):
    def _app(self, shorten_limit=1, redirect_limit=100, admin_limit=30, window=60):
        limiter = RateLimiter(
            rules={
                "shorten": RateLimitRule(shorten_limit, window),
                "redirect": RateLimitRule(redirect_limit, window),
                "admin": RateLimitRule(admin_limit, window),
            }
        )
        return WSGIApp(limiter=limiter)

    def test_shorten_within_limit_has_headers(self):
        app = self._app(shorten_limit=5)
        status, headers, _ = call(
            app, "POST", "/api/shorten", json.dumps({"url": "https://example.com/a"})
        )
        self.assertEqual(status, 201)
        self.assertEqual(headers["X-RateLimit-Limit"], "5")

    def test_shorten_over_limit_returns_429(self):
        app = self._app(shorten_limit=1)
        status1, _, _ = call(
            app, "POST", "/api/shorten", json.dumps({"url": "https://example.com/a"})
        )
        status2, headers2, body2 = call(
            app, "POST", "/api/shorten", json.dumps({"url": "https://example.com/b"})
        )
        self.assertEqual(status1, 201)
        self.assertEqual(status2, 429)
        self.assertIn("Retry-After", headers2)
        self.assertEqual(json.loads(body2)["error"], "rate limit exceeded")

    def test_redirect_rate_limited_independently_of_shorten(self):
        app = self._app(shorten_limit=1, redirect_limit=1)
        _, _, body = call(
            app, "POST", "/api/shorten", json.dumps({"url": "https://example.com/x"})
        )
        code = json.loads(body)["code"]
        status1, _, _ = call(app, "GET", "/" + code)
        status2, headers2, _ = call(app, "GET", "/" + code)
        self.assertEqual(status1, 302)
        self.assertEqual(status2, 429)
        self.assertIn("Retry-After", headers2)

    def test_admin_metrics_endpoint(self):
        app = self._app(shorten_limit=1)
        call(app, "POST", "/api/shorten", json.dumps({"url": "https://example.com/a"}))
        call(app, "POST", "/api/shorten", json.dumps({"url": "https://example.com/b"}))
        status, _, body = call(app, "GET", "/admin/metrics")
        self.assertEqual(status, 200)
        payload = json.loads(body)
        self.assertIn("shorten", payload["metrics"])
        self.assertEqual(payload["metrics"]["shorten"]["allowed"], 1)
        self.assertEqual(payload["metrics"]["shorten"]["denied"], 1)
        self.assertEqual(payload["rate_limits"]["shorten"]["limit"], 1)

    def test_admin_update_rule_takes_effect(self):
        app = self._app(shorten_limit=1)
        status, _, body = call(
            app,
            "PUT",
            "/admin/config/rate-limits/shorten",
            json.dumps({"limit": 3, "window_seconds": 60}),
        )
        self.assertEqual(status, 200)
        self.assertEqual(json.loads(body)["limit"], 3)
        # Now three shortens should succeed before a fourth is denied.
        for i in range(3):
            status, _, _ = call(
                app, "POST", "/api/shorten", json.dumps({"url": f"https://example.com/{i}"})
            )
            self.assertEqual(status, 201)
        status, _, _ = call(
            app, "POST", "/api/shorten", json.dumps({"url": "https://example.com/last"})
        )
        self.assertEqual(status, 429)

    def test_admin_update_rule_rejects_bad_input(self):
        app = self._app()
        status, _, _ = call(
            app, "PUT", "/admin/config/rate-limits/shorten", json.dumps({"limit": -1})
        )
        self.assertEqual(status, 400)

    def test_health_alias(self):
        app = self._app()
        status, _, _ = call(app, "GET", "/health")
        self.assertEqual(status, 200)


if __name__ == "__main__":
    unittest.main()
